"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[370],{68510(e){e.exports=JSON.parse('{"tag":{"label":"complexity-classes","permalink":"/azeon/p-vs-np/tags/complexity-classes","allTagsPath":"/azeon/p-vs-np/tags","count":4,"items":[{"id":"foundations/defining-the-class-np","title":"Defining the Class NP","description":"What does it actually mean for a problem to be \\"verifiable fast\\"? This post builds the formal definition of NP from the ground up, using the Rubik\'s Cube, Sudoku, and the strange but satisfying idea of a certificate.","permalink":"/azeon/p-vs-np/foundations/defining-the-class-np"},{"id":"foundations/defining-the-class-p","title":"Defining the Class P","description":"What does it actually mean for a problem to be \\"solvable fast\\"? This post builds the formal definition of the complexity class P from the ground up, using sorting, binary search, and the contrast between polynomial and exponential growth.","permalink":"/azeon/p-vs-np/foundations/defining-the-class-p"},{"id":"complexity-zoo/the-class-conp","title":"The Class coNP","description":"NP is about problems where a yes has a short proof. Flip it, and you get coNP, where a no has a short proof. It sounds like a small twist. It turns out to be its own unsolved problem, sitting right next to P vs NP.","permalink":"/azeon/p-vs-np/complexity-zoo/the-class-conp"},{"id":"foundations/the-core-question-does-p-equal-np","title":"The Core Question","description":"We have built every piece separately. Now we put them together and ask the question that has haunted mathematics and computer science for over fifty years.","permalink":"/azeon/p-vs-np/foundations/the-core-question-does-p-equal-np"}],"unlisted":false}}')}}]);